mapper.update:
UPDATE inventory_stock_position
SET quantity = quantity - #{delta},
    revision = revision + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE household_id = #{householdId}
  AND lot_id = #{lotId}
  AND location_id = #{locationId}
  AND quantity - #{delta} >= 0

mapper.select:
SELECT sp.id, sp.household_id, sp.lot_id, sp.location_id, sp.quantity, sp.revision,
       sp.created_at, sp.updated_at
FROM inventory_stock_position sp

    sp.household_id = #{householdId}
    AND EXISTS (SELECT 1 FROM inventory_lot l WHERE l.id = sp.lot_id AND l.item_id = #{itemId})
    AND sp.location_id = #{locationId}

ORDER BY ${orderBy}

SELECT sp.id, sp.lot_id AS lotId, sp.location_id AS locationId, sp.quantity, sp.revision, sp.created_at AS createdAt, sp.updated_at AS updatedAt, l.item_id AS itemId, l.lot_number AS lotNumber, l.serial_number AS serialNumber, l.expiry_date AS expiryDate, i.name AS itemName, i.management_type AS itemManagementType, u.name AS unitName FROM inventory_stock_position sp JOIN inventory_lot l ON l.id = sp.lot_id AND l.household_id = sp.household_id JOIN catalog_item i ON i.id = l.item_id AND i.household_id = l.household_id LEFT JOIN catalog_unit u ON u.id = i.unit_id AND u.household_id = i.household_id
sp.household_id = #{householdId} AND l.item_id = #{itemId} AND sp.location_id = #{locationId}
ORDER BY ${orderBy} LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM inventory_stock_position sp
JOIN inventory_lot l ON l.id = sp.lot_id AND l.household_id = sp.household_id

    sp.household_id = #{householdId}
    AND l.item_id = #{itemId}
    AND sp.location_id = #{locationId}
